import math

def dew_point(t_c: float, rh: float) -> float:
    if not (0.0 < rh <= 100.0):
        raise ValueError("rh muss größer als 0 und kleiner gleich 100 sein.")

    a = 17.62
    b = 243.12

    gamma = math.log(rh) - math.log(100.0) + (a * t_c) / (b + t_c)
    return (b * gamma) / (a - gamma)

_ROMAN_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

_ROMAN_NUMERAL_PAIRS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
    (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def int_to_roman(n: int) -> str:
    if not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999")

    result = []
    for value, symbol in _ROMAN_NUMERAL_PAIRS:
        count, n = divmod(n, value)
        if count:
            result.append(symbol * count)

    return "".join(result)


def roman_to_int(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("s must be a non-empty Roman numeral string")
    if len(s) > 15:
        raise ValueError("invalid Roman numeral string")
    if any(char not in _ROMAN_VALUES for char in s):
        raise ValueError("invalid Roman numeral string")

    total = 0
    length = len(s)

    for i, char in enumerate(s):
        value = _ROMAN_VALUES[char]
        if i + 1 < length and _ROMAN_VALUES[s[i + 1]] > value:
            total -= value
        else:
            total += value

    if total < 1 or total > 3999:
        raise ValueError("Roman numeral value must be between 1 and 3999")
    if int_to_roman(total) != s:
        raise ValueError("invalid Roman numeral string")

    return total

def merge_intervals(iv: list[tuple[float, float]]) -> list[tuple[float, float]]:
    for start, end in iv:
        if start > end:
            raise ValueError("Intervall ist ungültig: start > end")

    sorted_intervals = sorted(iv, key=lambda interval: (interval[0], interval[1]))

    merged: list[tuple[float, float]] = []

    for start, end in sorted_intervals:
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        else:
            prev_start, prev_end = merged[-1]
            merged[-1] = (prev_start, max(prev_end, end))

    return merged

import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes: set[str] = set(deps)
    for node_deps in deps.values():
        nodes.update(node_deps)

    indegree: dict[str, int] = {node: 0 for node in nodes}
    dependents: dict[str, list[str]] = {node: [] for node in nodes}

    for node, node_deps in deps.items():
        for dep in set(node_deps):
            indegree[node] += 1
            dependents[dep].append(node)

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)

    order: list[str] = []
    while available:
        node = heapq.heappop(available)
        order.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependency graph")

    return order

def crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF
    poly = 0x1021

    for byte in data:
        crc ^= byte << 8

        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ poly) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF

    return crc

def linfit(x: list[float], y: list[float]) -> tuple[float, float, float]:
    if len(x) != len(y):
        raise ValueError

    n = len(x)
    if n < 2:
        raise ValueError

    x0 = x[0]
    if all(xi == x0 for xi in x):
        raise ValueError

    y0 = y[0]
    if all(yi == y0 for yi in y):
        return 0.0, float(y0), 1.0

    x_mean = sum(x) / n
    y_mean = sum(y) / n

    ss_x = 0.0
    ss_xy = 0.0
    ss_y = 0.0

    for xi, yi in zip(x, y):
        dx = xi - x_mean
        dy = yi - y_mean
        ss_x += dx * dx
        ss_xy += dx * dy
        ss_y += dy * dy

    if ss_x == 0.0:
        raise ValueError

    slope = ss_xy / ss_x
    intercept = y_mean - slope * x_mean

    if n == 2 or ss_y == 0.0:
        return slope, intercept, 1.0

    denom = (ss_x ** 0.5) * (ss_y ** 0.5)
    if denom == 0.0:
        r_squared = 1.0
    else:
        r_squared = (ss_xy / denom) ** 2
        if r_squared < 0.0:
            r_squared = 0.0
        elif r_squared > 1.0:
            r_squared = 1.0

    return slope, intercept, r_squared

import heapq


def sliding_median(values: list[float], k: int) -> list[float]:
    if k < 1:
        raise ValueError("k must be at least 1")
    n = len(values)
    if k > n:
        raise ValueError("k must not exceed len(values)")

    heappush = heapq.heappush
    heappop = heapq.heappop

    low = []
    high = []

    active = bytearray([1]) * n
    side = bytearray(n)

    low_size = 0
    high_size = 0

    result = []
    append = result.append

    def clean_low() -> None:
        while low and not active[low[0][1]]:
            heappop(low)

    def clean_high() -> None:
        while high and not active[high[0][1]]:
            heappop(high)

    def move_low_to_high() -> None:
        nonlocal low_size, high_size
        clean_low()
        neg_value, idx = heappop(low)
        low_size -= 1
        high_size += 1
        heappush(high, (-neg_value, idx))
        side[idx] = 1

    def move_high_to_low() -> None:
        nonlocal low_size, high_size
        clean_high()
        value, idx = heappop(high)
        high_size -= 1
        low_size += 1
        heappush(low, (-value, idx))
        side[idx] = 0

    for i, value in enumerate(values):
        clean_low()
        clean_high()

        if low_size == 0 or value <= -low[0][0]:
            heappush(low, (-value, i))
            side[i] = 0
            low_size += 1
        else:
            heappush(high, (value, i))
            side[i] = 1
            high_size += 1

        if low_size > high_size + 1:
            move_low_to_high()
        elif high_size > low_size:
            move_high_to_low()

        if i >= k:
            out = i - k
            if active[out]:
                active[out] = 0
                if side[out] == 0:
                    low_size -= 1
                else:
                    high_size -= 1

                if low_size > high_size + 1:
                    move_low_to_high()
                elif high_size > low_size:
                    move_high_to_low()

        if i >= k - 1:
            clean_low()
            clean_high()
            if low_size == high_size:
                append((-low[0][0] + high[0][0]) / 2.0)
            else:
                append(-low[0][0])

    return result

from math import sqrt


class RunningStats:
    def __init__(self) -> None:
        self._count = 0
        self._mean = 0.0
        self._m2 = 0.0

    def add(self, x: float) -> None:
        x = float(x)
        self._count += 1
        delta = x - self._mean
        self._mean += delta / self._count
        self._m2 += delta * (x - self._mean)

    @property
    def count(self) -> int:
        return self._count

    @property
    def mean(self) -> float:
        if self._count == 0:
            return 0.0
        return self._mean

    @property
    def variance(self) -> float:
        if self._count < 2:
            return 0.0
        result = self._m2 / (self._count - 1)
        if result < 0.0 and result > -1e-12:
            return 0.0
        return result

    @property
    def std(self) -> float:
        if self._count < 2:
            return 0.0
        result = self.variance
        if result <= 0.0:
            return 0.0
        return sqrt(result)

from math import exp


def rh_after_mixing(t1, rh1, m1, t2, rh2, m2, p=101325.0) -> tuple[float, float]:
    if m1 <= 0 or m2 <= 0:
        raise ValueError("Trockenluft-Massenstroeme muessen groesser als 0 sein.")
    if p <= 0:
        raise ValueError("Gesamtdruck muss groesser als 0 sein.")

    def e_sat(t: float) -> float:
        denom = 243.12 + t
        if denom <= 0.0:
            raise ValueError("Temperatur liegt ausserhalb des gueltigen Bereichs.")
        return 611.2 * exp(17.62 * t / denom)

    e1 = (rh1 / 100.0) * e_sat(t1)
    e2 = (rh2 / 100.0) * e_sat(t2)

    if e1 >= p or e2 >= p:
        raise ValueError("Dampfdruck erreicht oder uebersteigt den Gesamtdruck.")

    x1 = 0.622 * e1 / (p - e1)
    x2 = 0.622 * e2 / (p - e2)

    m_total = m1 + m2
    t_mix = (m1 * t1 + m2 * t2) / m_total
    x_mix = (m1 * x1 + m2 * x2) / m_total

    e_mix = p * (x_mix / (0.622 + x_mix)) if x_mix != 0.0 else 0.0

    e_sat_mix = e_sat(t_mix)
    if e_sat_mix <= 0.0:
        rh_mix = 0.0 if e_mix <= 0.0 else float("inf")
    else:
        rh_mix = 100.0 * e_mix / e_sat_mix

    return float(t_mix), float(rh_mix)
